package com.muthumol.player.dummy;
import android.app.*;import android.content.*;import android.widget.*;import java.util.*;import org.json.*;
final class MovieDetails {
 static String override(Context c,Movie m){return c.getSharedPreferences("metadata-corrections",0).getString("title:"+m.cacheIdentity(),m.title);}
 static void show(MainActivity a,Movie m){AlertDialog d=Ui.dialog(a).setTitle(MediaTitle.parse(override(a,m)).display()).setMessage(m.details()+"\n\nLoading description and ratings…").setPositiveButton("Play",(x,w)->a.playEpisode(m,false)).setNeutralButton("Versions",(x,w)->a.chooseVersions(m)).setNegativeButton("Close",null).show();MetadataStore.get(a).load(m,data->{if(!d.isShowing())return;StringBuilder text=new StringBuilder(m.details());if(!data.optString("genres").isEmpty())text.append("\n\n").append(data.optString("genres"));text.append("\n\n").append(data.optString("overview","No verified description available."));JSONObject ratings=data.optJSONObject("ratings");if(ratings!=null){Iterator<String> names=ratings.keys();while(names.hasNext()){String name=names.next();text.append("\n").append(name).append(": ").append(ratings.optString(name));}}if(data.has("source"))text.append("\n\nSource: ").append(data.optString("source"));d.setMessage(text.toString());});}
 static void correct(MainActivity a,Movie m){SharedPreferences p=a.getSharedPreferences("metadata-corrections",0);LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText title=Ui.input(a,"Correct title (include year; episode if needed)",false),imdb=Ui.input(a,"IMDb id, e.g. tt0133093 (optional)",false),group=Ui.input(a,"Versions group name (optional; same for copies)",false);title.setText(override(a,m));imdb.setText(p.getString("imdb:"+m.cacheIdentity(),""));group.setText(m.groupOverride);box.addView(title);box.addView(imdb);box.addView(group);Ui.dialog(a).setTitle("Correct title / artwork").setView(box).setPositiveButton("Save",(d,w)->{String name=title.getText().toString().trim(),id=imdb.getText().toString().trim();if(name.isEmpty()||!id.isEmpty()&&!id.matches("tt[0-9]{5,10}")){Ui.message(a,"Correction","Use a title and a valid IMDb id, or leave the id empty.");return;}p.edit().putString("title:"+m.cacheIdentity(),name).putString("imdb:"+m.cacheIdentity(),id).putString("group:"+m.cacheIdentity(),group.getText().toString().trim()).apply();m.groupOverride=group.getText().toString().trim();MetadataStore.get(a).invalidate(m);a.artworks.invalidate(m);a.shelfKey=null;a.changed();}).setNegativeButton("Cancel",null).show();}
}
